// ELEMENTS:
// 1. Fundo branco com o filete vermelho no topo e uma grelha de pontos azul muito leve
// 2. Eyebrow (azul royal) e título em navy
// 3. Fluxograma vertical: um cartão azul-claro por condição (items "Rótulo: valor"), medalhão azul
//    com visto, setas tracejadas que se desenham até ao seguinte (times = s em que cada nó entra)
// 4. Resultado (result) num cartão vermelho com raios a abrir, em resultAt (s)
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const TINT = "#E8EEF9";
const LINEL = "#D5DCE8";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const GREY = "#5A6370";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.6));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const FluxogramaCondicoes: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const title = String(p.title ?? anim.text ?? "").trim();
  const result = String(p.result ?? "").trim();
  const raw = Array.isArray(p.items) ? (p.items as unknown[]).map(String) : [];
  const items = raw.map((s) => {
    const i = s.indexOf(":");
    return i > 0 ? { label: s.slice(0, i).trim(), value: s.slice(i + 1).trim() } : { label: "", value: s.trim() };
  });
  const times = Array.isArray(p.times) ? (p.times as unknown[]).map(Number) : [];
  const at = (i: number) => (Number.isFinite(times[i]) ? times[i] : 0.5 + i * 1.2);
  const resultAt = Number(p.resultAt ?? at(items.length)) || at(items.length);

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const nodeH = 170 * u;
  const gapH = 70 * u;
  const res = show(resultAt, 0.6, BACK);

  return (
    <AbsoluteFill style={{ backgroundColor: WHITE, overflow: "hidden" }}>
      <AbsoluteFill style={{ backgroundImage: `radial-gradient(${TINT} ${3 * u}px, transparent ${3 * u}px)`, backgroundSize: `${44 * u}px ${44 * u}px`, opacity: 0.9 }} />
      <AbsoluteFill style={{ justifyContent: "center", padding: `0 ${80 * u}px`, gap: 50 * u }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 18 * u, opacity: show(0.05), transform: `translateY(${(1 - show(0.05)) * 26 * u}px)` }}>
          {eyebrow ? (
            <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: BLUE }}>
              <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
              {eyebrow}
            </div>
          ) : null}
          <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 80 * u, lineHeight: 1.05, color: NAVY }}>{title}</div>
        </div>
        <div style={{ display: "flex", flexDirection: "column" }}>
          {items.map((it, i) => {
            const k = show(at(i), 0.55, BACK);
            const check = show(at(i) + 0.35, 0.45);
            const nextAt = i + 1 < items.length ? at(i + 1) : resultAt;
            const link = show(at(i) + 0.5, Math.max(0.3, nextAt - at(i) - 0.5));
            return (
              <div key={i} style={{ display: "flex", flexDirection: "column" }}>
                <div style={{ height: nodeH, background: TINT, border: `${2 * u}px solid ${check > 0.5 ? BLUE : LINEL}`, borderRadius: 24 * u, display: "flex", alignItems: "center", gap: 30 * u, padding: `0 ${34 * u}px`, opacity: Math.min(1, k * 1.4), transform: `scale(${0.85 + 0.15 * k})`, boxShadow: "0 14px 30px rgba(1,59,169,0.12)" }}>
                  <div style={{ width: 92 * u, height: 92 * u, borderRadius: "50%", background: check > 0 ? BLUE : WHITE, border: `${2 * u}px solid ${BLUE}`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <svg width={52 * u} height={52 * u} viewBox="0 0 52 52">
                      <path d="M12 27 L22 37 L41 16" fill="none" stroke={WHITE} strokeWidth={5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - check} />
                    </svg>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 6 * u }}>
                    {it.label ? <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 26 * u, letterSpacing: "0.28em", textTransform: "uppercase", color: GREY }}>{it.label}</div> : null}
                    <div style={{ fontFamily: FONTS.display, fontWeight: 600, fontSize: 56 * u, lineHeight: 1.1, color: NAVY, fontVariantNumeric: "lining-nums" }}>{it.value}</div>
                  </div>
                </div>
                <svg width={120 * u} height={gapH} viewBox="0 0 120 70" style={{ alignSelf: "flex-start", marginLeft: 54 * u, overflow: "visible" }}>
                  <path d="M60 2 V58" fill="none" stroke={BLUE} strokeWidth={3} strokeDasharray="6 7" strokeDashoffset={-f * 0.6} opacity={link > 0 ? 1 : 0} style={{ clipPath: `inset(0 0 ${(1 - link) * 100}% 0)` }} />
                  <path d="M50 52 L60 64 L70 52" fill="none" stroke={BLUE} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" opacity={link > 0.9 ? 1 : 0} />
                </svg>
              </div>
            );
          })}
          {result ? (
            <div style={{ position: "relative", alignSelf: "stretch" }}>
              <svg width={W} height={400 * u} viewBox="-200 -200 400 400" style={{ position: "absolute", left: -80 * u, top: -120 * u, opacity: (1 - show(resultAt + 0.3, 1.2)) * (res > 0 ? 1 : 0) }}>
                {Array.from({ length: 14 }, (_, k) => {
                  const a = (k / 14) * Math.PI * 2;
                  const r1 = 70 + 60 * show(resultAt, 1.0);
                  return <line key={k} x1={Math.cos(a) * r1} y1={Math.sin(a) * r1 * 0.55} x2={Math.cos(a) * (r1 + 30)} y2={Math.sin(a) * (r1 + 30) * 0.55} stroke={RED} strokeWidth={4} strokeLinecap="round" />;
                })}
              </svg>
              <div style={{ position: "relative", background: RED, borderRadius: 24 * u, padding: `${40 * u}px ${40 * u}px`, display: "flex", alignItems: "center", justifyContent: "center", gap: 24 * u, transform: `scale(${res})`, boxShadow: "0 20px 40px rgba(222,33,43,0.35)" }}>
                <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 72 * u, color: WHITE, lineHeight: 1 }}>{result}</div>
              </div>
            </div>
          ) : null}
        </div>
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
    </AbsoluteFill>
  );
};

export default FluxogramaCondicoes;
